python - <<'PY'
import numpy as np,json
from PIL import Image
folder='/app/output/tilt_lift';m=json.load(open(folder+'/meta.json'))
for c,regions in [('front',{'tip':(145,175,100,124),'tool':(140,190,124,145)}),('side',{'tip':(95,145,90,125),'tool':(118,155,122,150)}),('oblique',{'tip':(140,190,95,130),'tool':(120,180,120,155)})]:
 cal=m['cameras'][c];K=np.array(cal['intrinsic_cv']);T=np.array(cal['cam2world_gl']);im=np.array(Image.open(folder+f'/last/{c}.jpg'));d=np.load(folder+f'/depth_{c}.npy')[0].astype(float);y,x=np.mgrid[:240,:320];X=(x-K[0,2])*d/K[0,0];Y=(K[1,2]-y)*d/K[1,1];W=np.stack([X,Y,-d,np.ones_like(d)],-1)@T.T
 print('\n',c)
 for name,(x0,x1,y0,y1) in regions.items():
  sub=W[y0:y1,x0:x1,:3].reshape(-1,3);rgb=im[y0:y1,x0:x1].reshape(-1,3);dep=d[y0:y1,x0:x1].ravel();
  if name=='tip': sel=(rgb.mean(1)>100)&((rgb.max(1)-rgb.min(1))<120)&(dep<2)&(sub[:,2]>.55)&(sub[:,2]<.85)
  else: sel=(rgb.mean(1)<170)&(rgb.mean(1)>20)&(dep<2)&(sub[:,2]>.45)&(sub[:,2]<.65)
  print(name,'n',sel.sum(),'rgb',rgb[sel].mean(0).round(1) if sel.sum() else None,'xyz mean',sub[sel].mean(0).round(3) if sel.sum() else None,'med',np.median(sub[sel],0).round(3) if sel.sum() else None,'px',np.mean(np.where(sel)[0]),np.mean(np.where(sel)[1]) if sel.sum() else None)
